{
  "technical_and_design_decisions": [
    "Reuse the existing Apache Ambari plugin framework as the foundation for the YARN integration rather than building a new management stack.",
    "Use Spring Cloud Config Server (native Spring Cloud component) as the external configuration backend for spring-bus, leveraging its native Spring integration.",
    "Adopt a micro-benchmarking approach (JMH-based) for channel performance and serialization baseline measurements to produce reproducible numbers.",
    "Implement fsUri=file:// support by short-circuiting at the Hadoop FileSystem factory layer so the same XD jobs run unchanged against local files.",
    "Pass Sqoop system properties by extending the existing Hadoop launcher abstraction rather than introducing a new subprocess mechanism.",
    "Treat the spring-bus architecture review (U5) as a design/documentation deliverable that produces a gap report and an actionable roadmap, not a code rewrite.",
    "For the XD 1.2 RC -> 1.2 GA upgrade (U6), focus on plugin metadata, packaging, and documentation rather than re-implementing XD itself."
  ],
  "assumptions": [
    "A single developer performs all activities, with full familiarity with the Spring XD, Spring Integration, and Spring Cloud codebases.",
    "Development, integration test, and YARN/Ambari sandbox environments are already available and maintained by the team.",
    "No major architectural rewrites are required; changes are additive and backward compatible where reasonable.",
    "User stories U1, U2, and U6 are the largest work items; U3-U5 are investigative/measurement-focused; U7 and U8 are small, well-scoped enhancements.",
    "Documentation updates are estimated as a separate cross-cutting activity rather than embedded inside each feature.",
    "All effort values represent work-hours of focused development work (excluding meetings, waiting, or environment downtime).",
    "Spring XD is treated as the target system; Spring Framework 6 / Java 17+ baseline is not part of this increment."
  ],
  "activities": [
    {
      "activity_id": "U1.1",
      "activity_name": "Design Ambari-YARN integration for Spring XD",
      "activity_description": "Analyze YARN deployment models, design how Spring XD containers are managed by an Ambari-managed cluster, and produce an integration design document covering service definitions and lifecycle hooks.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U1.2",
      "activity_name": "Implement Ambari plugin for Spring XD on YARN",
      "activity_description": "Implement Ambari service definitions, alerts, configuration management, and the YARN application master/client integration required to start XD containers on a YARN cluster managed by Ambari.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "U1.3",
      "activity_name": "Test Ambari on YARN integration",
      "activity_description": "Set up an Ambari+YARN sandbox, exercise install/start/stop/upgrade flows, and validate that XD cluster members register correctly and recover from container failures.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U2.1",
      "activity_name": "Integrate Spring Cloud Config Server with spring-bus",
      "activity_description": "Add Spring Cloud Config Client support to spring-bus modules, including bootstrap configuration, environment bootstrap order, and secure property source wiring.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "U2.2",
      "activity_name": "Migrate spring-bus module configuration to config server",
      "activity_description": "Move existing local property files and hard-coded defaults into a Git-backed config repository and refactor module bootstrap to resolve properties from the config server.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "U2.3",
      "activity_name": "Test spring-cloud-config integration",
      "activity_description": "Verify config refresh, profile-based property resolution, and failure handling when the config server is unreachable.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U3.1",
      "activity_name": "Profile and benchmark SI 4.2 channel performance",
      "activity_description": "Build a reproducible benchmark harness for the SI 4.2 channel primitives (DirectChannel, ExecutorChannel, PublishSubscribeChannel, QueueChannel), run profiling, and collect baseline numbers under varying load.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "U3.2",
      "activity_name": "Implement channel performance improvements",
      "activity_description": "Apply targeted improvements based on profiling (e.g., reducing contention, optimizing executor sizing, refining hand-off logic) and re-run the benchmarks to confirm gains.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U4.1",
      "activity_name": "Build XD serialization baseline measurement harness",
      "activity_description": "Create a benchmark module that measures serialization/deserialization latency and throughput for typical XD payloads across supported codecs (Java, Kryo, JSON).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U4.2",
      "activity_name": "Run and document serialization benchmarks",
      "activity_description": "Execute the harness against representative workloads, capture results, and produce a baseline report identifying the most expensive codecs and payload patterns.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U5.1",
      "activity_name": "Spring-bus architecture review and gap analysis",
      "activity_description": "Review the current spring-bus architecture and design specs, identify foundation-level gaps (e.g., message contract, error handling, scalability), and deliver a written review with recommended actions.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U6.1",
      "activity_name": "Update Ambari plugin for XD 1.2 GA",
      "activity_description": "Bump the Ambari plugin's packaged Spring XD version from 1.2 RC to 1.2 GA, regenerate package metadata, and verify install/upgrade paths in the Ambari stack.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U6.2",
      "activity_name": "Update upgrade documentation for XD 1.2 GA",
      "activity_description": "Update the Ambari-plugin-based upgrade guide to reflect the 1.2 GA bits, including any new/changed configuration parameters.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U7.1",
      "activity_name": "Implement fsUri=file:// support",
      "activity_description": "Allow fsUri=file:// so that jdbchdfs (and other Hadoop FileSystem users) resolve to Hadoop's LocalFileSystem, falling back to current behavior when the URI is unset.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U7.2",
      "activity_name": "Test file:// URI handling",
      "activity_description": "Validate single-node scenarios (local CSV loading via jdbchdfs) and confirm documented limitations for multi-container/multi-host deployments.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U8.1",
      "activity_name": "Implement system properties support for Sqoop job",
      "activity_description": "Expose a new option in the Sqoop job module to pass JVM system properties into the spawned Sqoop process (e.g., -Xmx, connector-specific flags) and propagate them through the Hadoop launcher.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U8.2",
      "activity_name": "Test Sqoop system properties",
      "activity_description": "Verify that specified system properties are actually applied to the Sqoop JVM, including memory settings and connector-specific options, and that defaults are preserved when unset.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "CC.1",
      "activity_name": "Cross-feature integration testing",
      "activity_description": "Run end-to-end integration tests covering the combination of new Ambari/YARN deployment, config server-backed spring-bus, fsUri=file://, and Sqoop system properties in a single XD cluster.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "CC.2",
      "activity_name": "Documentation updates",
      "activity_description": "Update reference, admin, and operations documentation to cover the new Ambari-on-YARN option, spring-bus config server usage, performance findings, file:// URI caveat, and Sqoop system properties option.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "CC.3",
      "activity_name": "Build and release engineering",
      "activity_description": "Update build scripts, dependency versions, and release artifacts so that the Ambari plugin ships with XD 1.2 GA and the spring-bus modules can be built with the new config server dependency.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 294
  }
}
